    for(int i = 0;i < str.length();i++){
        int c = str.charAt(i);
        if(c > 127){
           session.offset += 3;
           lb.put((byte)(0xc0 | (0xf & c >> 6)));
           lb.put((byte)(0x80 | (0x3f & c)));
        }else if(c > 31){
            session.offset += 2;
            lb.put((byte)(0xc0 | (0x1 & c >> 6)));
            lb.put((byte)(0x80 | (0x3f & c)));
