public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        String path = u.getPath();
        List<String> segments = new ArrayList<>();
        int start = 0;

        while (start < path.length()) {
            int index;
            if (decode) {
                index = path.indexOf('%', start);
            } else {
                index = path.indexOf('/', start);
            }

            if (index == -1) {
                segments.add(path.substring(start));
                break;
            } else {
                if (decode) {
                    char highDigit = path.charAt(index + 1);
                    char lowDigit = path.charAt(index + 2);
                    int value = 16 * Character.digit(highDigit, 16) + Character.digit(lowDigit, 16);
                    segments.add(value + "");
                } else {
                    segments.add(path.substring(start, index));
                }
                start = index + 3;
            }
        }

        return segments;
    }

