public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double halfWidth = box.getWidth() / 2.0;
    return new Pair<>(new Box2D(box.getMinX(), box.getMinY(), halfWidth, box.getHeight()), new Box2D(box.getMinX() + halfWidth, box.getMinY(), box.getWidth(), box.getHeight()));
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double width = box.getWidth();
    double halfWidth = width / 2.0;
    double centerX = box.getX() + halfWidth;

    Box2D box1 = new Box2D(box.getX(), box.getY(), centerX, box.getHeight());
    Box2D box2 = new Box2D(centerX, box.getY(), box.getX() + width, box.getHeight());

    return new Pair<>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double x = box.getX();
    double y = box.getY();
    double width = box.getWidth();
    double height = box.getHeight();

    Box2D boxLeft = new Box2D(x, y, width / 2, height);
    Box2D boxRight = new Box2D(x + width / 2, y, width / 2, height);

    return new Pair<>(boxLeft, boxRight);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double splitPoint = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2;
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), splitPoint, box.getMaxY());
    Box2D rightBox = new Box2D(splitPoint, box.getMinY(), box.getMaxX(), box.getMaxY());
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double midPoint = box.getMinX() + 0.5 * box.getWidth();
    double leftWidth = midPoint - box.getMinX();
    double rightWidth = box.getMaxX() - midPoint;

    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), leftWidth, box.getHeight());
    Box2D rightBox = new Box2D(midPoint, box.getMinY(), rightWidth, box.getHeight());

    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

