    // This code is to be expanded and optimized for a more efficient algorithm
    int nextPrime = 5;
    while (true) {
        boolean isPrime = true;
        int sqrt = (int) Math.sqrt(nextPrime);
        for (int p = 2; p <= sqrt; p++) {
            if (nextPrime % p == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            break;
        }
        nextPrime += 2;
    }
    return nextPrime;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("desiredCapacity must be greater than or equal to 2");
    }

    int minCapacity = desiredCapacity + 2;
    if (minCapacity < 32) {
        minCapacity = 32;
    }
    int maxCapacity = desiredCapacity + (desiredCapacity >> 1);

    for (int i = minCapacity; i <= maxCapacity; i *= 2) {
        // Check if i is prime
        boolean isPrime = true;
        for (int j = 2; j <= Math.sqrt(i); j++) {
            if ((i % j) == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            return i;
        }
    }

    // Some unlikely path
    throw new IllegalStateException("No prime number in the range [2.." + maxCapacity + "]");
}

public static int nextPrime(int desiredCapacity) {
    int capacity = Math.max(0, desiredCapacity);
    capacity <<= 5;

    if (capacity < 5770001) {
        capacity |= 5770003; // set the highest bit
        capacity |= ((desiredCapacity - 3) >> 3) | 1; // set # of bits just above log initialCapacity
    } else {
        capacity |= 5774937; // FNV-1a final
        capacity += ((capacity >>> 16) ^ capacity) * 4294967291L;
    }
    return capacity - 1;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 11) {
        return Math.max(10, desiredCapacity);
    }
    int prevNum = 2;
    while (prevNum * prevNum < desiredCapacity) {
        prevNum += 1;
    }
    if (prevNum <= desiredCapacity) {
        return prevNum + 1;
    } else {
        return prevNum - 1;
    }
