        for (int i = 2; i <= Math.sqrt(prime); i++) {
            if (prime % i == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            return prime;
        }

        prime += 2; // Increment by 2 to skip even numbers
    }
