            switch (c) {
                case 'n':
                    builder.append('\n');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                default:
                    builder.append(c);
                    inEscape = false;
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

