private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    int vCount = vertices.size();
    if (vCount <= 2) return true;

    for (V vertex : vertices) {
        Set<V> degree = new HashSet<>();
        for (V neighbor : graph.neighbors(vertex)) {
            if (vertices.contains(neighbor)) degree.add(neighbor);
        }

        if (degree.size() < vCount - 1) return false;
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    int vertexCount = vertices.size();
    for (V v : vertices) {
        if (graph.degree(v) < vertexCount - 1) {
            return false;
        }
    }
    return true;
}

private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    int size = vertices.size();
    if (size < 3) return true; // A graph with less than 3 vertices is always a clique
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                return false; // Find a vertex that is not connected to any other vertex
            }
        }
    }
    return true; // All vertices are connected to each other
}

private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    Set<Edge<V, E>> inducedSubgraph = new HashSet<>();
    for (V vertex : vertices) {
        for (V neighbor : graph.neighbors(vertex)) {
            inducedSubgraph.add(graph.getEdge(vertex, neighbor));
        }
    }
    return inducedSubgraph.size() == graph.numNodes();
}

