public static String encodeTemplateNames(String s) {
    StringBuilder encoded = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{' || c == '}') {
            encoded.append("%").append(Integer.toHexString((int) c).toUpperCase());
        } else {
            encoded.append(c);
        }
    }
    return encoded.toString();
}

