    // Add the multiple / together
    relativePath = relativePath.replace((char)32, '/');
    // Ensure that there are two /'s next to each other
    relativePath = relativePath.replaceAll("///".replaceAll("/", "\\/"), "/");
    // Replace '//' with '/'
    relativePath = relativePath.replace("//", "/");
    // Add the appropriate directory separator at the beginning and end
    if(path == null || path.isEmpty()){
        path = "";
    }else{
        if(path.charAt(path.length() - 1) != File.separatorChar){
            path += File.separatorChar;
        }
