    if (str == null || substring == null) {
        throw new IllegalArgumentException("Strings must not be null");
    }
    if (index < 0 || index > str.length()) {
        throw new IllegalArgumentException("Index must be within the range of the string length");
    }
    if (substring.length() > str.length() - index) {
        return false;
    }
    return str.regionMatches(index, substring, 0, substring.length());
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (index + substring.length() > str.length()) return false;
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) return false;
    }
    return true;
}

